def merge(self, intervals: list[list[int]]) -> list[list[int]]:
    arr = [iv[:] for iv in intervals]
    changed = True
    while changed:
        changed = False
        for a in range(len(arr)):
            for b in range(a + 1, len(arr)):
                x, y = arr[a], arr[b]
                if x[0] <= y[1] and y[0] <= x[1]:
                    arr[a] = [min(x[0], y[0]), max(x[1], y[1])]
                    arr.pop(b)
                    changed = True
                    break
            if changed:
                break
    return arr

